/* Series containers retain each season's tracking; grouping is not a reset or rewatch. */
const SeriesMerge=(()=>{
 const M=SeasonModel,say=(zh,en)=>I18n.getLanguage()==='en-US'?en:zh;let preview=null;
 const related=a=>M.leaves(library).filter(b=>M.isSeason(b)&&M.seriesKey(b)===M.seriesKey(a)).sort((a,b)=>a.seasonNumber-b.seasonNumber);
 const revision=()=>JSON.stringify(['anishelf-library-v1','anishelf-watch-history-v1','anishelf-lists-v1','anishelf-series-archive-v1'].map(key=>AppStorage.getItem(key)));
 function selected(){return preview?.split?preview.parent.seasonEntries:$$('#seriesMergeRows [data-merge-season]:checked').map(input=>preview.items[Number(input.dataset.mergeSeason)])}
 function updateNotes(){if(!preview)return;$('#seriesMergeNotes').textContent=M.mergeNotes(...selected().map(a=>a.note),preview.split?preview.parent.seriesNote:'')||say('无备注','No notes')}
 function open(a){const split=M.isMerged(a),originals=SeasonManager.archive(),items=(split?a.seasonEntries:related(a)).map(c=>!split&&c.seasonNumber===1?{...c,note:M.mergeNotes(c.note,...originals.filter(r=>M.seriesKey(r.source)===M.seriesKey(c)).map(r=>r.source.note))}:c);preview={split,items,parent:a,revision:revision()};$('#seriesMergeTitle').textContent=say(split?'还原独立季度':'将季度合并为系列',split?'Restore independent seasons':'Merge seasons into a series');$('#seriesMergeHelp').textContent=say(split?'将还原各季的进度、重看次数、备注和观看日期。系列补充备注只加入第一季；没有第一季时保留在档案。':'只合并同一系列的季度。各季的进度、重看次数、评分、日期及观看历史保留，notes 按季度顺序拼接。合并后的系列可展开编辑各季。',split?'Restore each season’s progress, rewatches, notes and dates. Additional series notes go to Season 1, or stay archived if Season 1 is absent.':'Group seasons from the same series. Preserve per-season progress, rewatches, ratings, dates and history. Combine notes in season order. Open season records to continue editing.');
  $('#seriesMergeRows').innerHTML=items.map((item,index)=>'<label class="series-merge-row">'+(!split?'<input type="checkbox" data-merge-season="'+index+'" checked>':'')+'<span><strong>'+esc(M.label(item.seasonNumber))+'</strong><small>'+esc(statuses[item.status])+' · '+item.progress+' / '+item.episodes+' · '+say('重看 ','Rewatches ')+(item.rewatchCount||0)+'</small></span></label>').join('');$('#seriesMergeRows').onchange=updateNotes;$('#seriesMergeStatus').textContent='';$('#seriesMergeCommit').textContent=say(split?'确认还原季度':'确认合并',split?'Restore seasons':'Confirm merge');$('#seriesMergeDialog').showModal();updateNotes();
 }
 function commit(){if(!preview)return;try{if(revision()!==preview.revision)throw Error(say('资料已变化，请重新打开预览。','Data changed. Reopen the preview.'));const plan=preview.split?M.splitMergedPlan(preview.parent,library,WatchHistory.exportRecords(),AniLists.exportLists(),SeasonManager.archive()):M.mergePlan(selected(),library,WatchHistory.exportRecords(),AniLists.exportLists());M.validateCatalog(plan.library);WatchHistory.validate(plan.history);AniLists.validate(plan.lists);
   const writes={'anishelf-library-v1':JSON.stringify(plan.library),'anishelf-lists-v1':JSON.stringify(plan.lists)};if(plan.archive)writes['anishelf-series-archive-v1']=JSON.stringify(plan.archive);M.transaction(writes);library=plan.library;WatchHistory.replaceRecords(plan.history,library);AniLists.replaceLists(plan.lists);$('#seriesMergeDialog').close();closeDetailPanel();render();toast(say('已保存，观看记录保持不变','Saved. Viewing records are preserved.'));preview=null;
  }catch(error){$('#seriesMergeStatus').textContent=error.recoveryPending?say('恢复日志已保留，请重新打开页面恢复后继续。','Recovery data was retained. Reopen the page to restore data before continuing.'):error.name==='QuotaExceededError'?say('空间不足，操作未完成。请先导出备份。','Storage is full. The operation was not completed. Export a backup first.'):({'Select at least two seasons from the same series':say('请至少选择同一系列的两个季度。','Select at least two seasons from the same series.'),'Select all seasons already in the merged series':say('请保留已合并系列中的全部季度，再添加新季度。','Select all seasons already in the merged series before adding more.'),'Season no longer exists':say('季度记录已变化，请重新打开预览。','Season records changed. Reopen the preview.'),'Too many episodes in a merged series':say('合并后的总集数不能超过 9999。','A merged series cannot exceed 9999 episodes.')}[error.message]||error.message)}}
 $('#seriesMergeCommit').onclick=commit;
 const baseDetail=renderDetail;renderDetail=function(a){baseDetail(a);const section=document.createElement('section');section.className='detail-section series-records';
  if(M.isMerged(a)){const tracking=$('#detailTracking');if(tracking)tracking.hidden=true;const refresh=$('#refreshDetails');if(refresh)refresh.hidden=true;section.innerHTML='<h3>'+say('季度观看记录','Season records')+'</h3><p>'+say('系列进度表示首轮观看范围；统计包含每季各自的重看。点击季度继续编辑其记录。','Series progress represents the first viewing. Statistics include each season’s rewatches. Open a season to edit its records.')+'</p>'+a.seasonEntries.map((c,i)=>'<button data-open-merged-season="'+i+'">'+esc(M.label(c.seasonNumber))+' · '+esc(statuses[c.status])+' · '+c.progress+' / '+c.episodes+' · ↻ '+(c.rewatchCount||0)+'</button>').join('')+'<button id="splitMergedSeries">'+say('还原为独立季度','Restore independent seasons')+'</button><h3>'+say('全部备注','Combined notes')+'</h3><pre class="merged-notes"></pre><label>'+say('系列补充备注（还原时加入第一季）','Additional series notes (restored to Season 1)')+'<textarea id="seriesExtraNote"></textarea></label><button id="saveSeriesNote">'+say('保存系列备注及评分','Save series notes and rating')+'</button>';
   $('#detailBody .detail-content').append(section);section.querySelector('.merged-notes').textContent=a.note||'';section.querySelector('#seriesExtraNote').value=a.seriesNote||'';section.querySelectorAll('[data-open-merged-season]').forEach(b=>b.onclick=()=>openDetail(a.seasonEntries[Number(b.dataset.openMergedSeason)].id));section.querySelector('#splitMergedSeries').onclick=()=>open(a);section.querySelector('#saveSeriesNote').onclick=()=>{try{const next=patchLibraryEntry(a.id,{seriesNote:section.querySelector('#seriesExtraNote').value,rating:detailDraft.rating});AppStorage.setItem('anishelf-library-v1',JSON.stringify(next));library=next;Object.assign(a,findLibraryEntry(a.id));renderDetail(findLibraryEntry(a.id));toast(t('观看记录已保存'))}catch(error){toast(error.message)}};
  }else if(M.isSeason(a)){const parent=library.find(root=>M.isMerged(root)&&root.seasonEntries.some(c=>c.id===a.id));if(parent){section.innerHTML='<button id="backToMergedSeries">← '+esc(parent.title)+'</button>';$('#detailBody .detail-content').append(section);section.querySelector('#backToMergedSeries').onclick=()=>openDetail(parent.id)}else if(related(a).length>=2){section.innerHTML='<button id="mergeRelatedSeasons">'+say('与其他季度合并为系列','Merge with other seasons')+'</button>';$('#detailBody .detail-content').append(section);section.querySelector('#mergeRelatedSeasons').onclick=()=>open(a)}}
 };
 const baseDelete=deleteAnime;deleteAnime=function(id){const parent=library.find(a=>M.isMerged(a)&&a.seasonEntries.some(c=>c.id===id));if(!parent)return baseDelete(id);const removed=parent.seasonEntries.find(c=>c.id===id),index=parent.seasonEntries.indexOf(removed),parentIndex=library.indexOf(parent),remaining=parent.seasonEntries.filter(c=>c.id!==id),next=remaining.length?M.patch(library,parent.id,{seasonEntries:remaining}):library.filter(a=>a.id!==parent.id);
  try{AppStorage.setItem('anishelf-library-v1',JSON.stringify(next));library=next;render();closeDetailPanel();toast(t('已删除「')+removed.title+'」');$('#toast').innerHTML=esc(t('已删除「')+removed.title+'」')+' <button id="undoDelete">'+t('撤销')+'</button>';clearTimeout(window.toastTimer);$('#undoDelete').onclick=()=>{if(findLibraryEntry(id))return;try{const current=library.find(a=>a.id===parent.id);let restored;if(current&&M.isMerged(current)){const seasons=[...current.seasonEntries];seasons.splice(index,0,removed);restored=M.patch(library,parent.id,{seasonEntries:seasons})}else{restored=[...library];restored.splice(parentIndex,0,parent)}AppStorage.setItem('anishelf-library-v1',JSON.stringify(restored));library=restored;render();toast(t('已恢复「')+removed.title+'」')}catch(error){toast(error.message)}};window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),8000)}catch(error){toast(error.message)}
 };
 return {open,commit};
})();
